 622	    /// Initialize the subprocess. This will NOT start it, this only sets
 623	    /// up the internal state necessary to start it later.
 624	    pub fn init(gpa: Allocator, cfg: Config) !Subprocess {
 625	        // We have a lot of maybe-allocations that all share the same lifetime
 626	        // so use an arena so we don't end up in an accounting nightmare.
 627	        var arena = std.heap.ArenaAllocator.init(gpa);
 628	        errdefer arena.deinit();
 629	        const alloc = arena.allocator();
 630	
 631	        // Get our env. If a default env isn't provided by the caller
 632	        // then we get it ourselves.
 633	        var env = cfg.env;
 634	        errdefer env.deinit();
 635	
 636	        // If we have a resources dir then set our env var
 637	        if (cfg.resources_dir) |dir| {
 638	            log.info("found Ghostty resources dir: {s}", .{dir});
 639	            try env.put("GHOSTTY_RESOURCES_DIR", dir);
 640	        }
 641	
 642	        // Set our TERM var. This is a bit complicated because we want to use
 643	        // the ghostty TERM value but we want to only do that if we have
 644	        // ghostty in the TERMINFO database.
 645	        //
 646	        // For now, we just look up a bundled dir but in the future we should
 647	        // also load the terminfo database and look for it.
 648	        if (cfg.resources_dir) |base| {
 649	            try env.put("TERM", cfg.term);
 650	            try env.put("COLORTERM", "truecolor");
 651	
 652	            // Assume that the resources directory is adjacent to the terminfo
 653	            // database
 654	            var buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
 655	            const dir = try std.mem.print(&buf, "{s}/terminfo", .{
 656	                std.fs.path.dirname(base) orelse unreachable,
 657	            });
 658	            try env.put("TERMINFO", dir);
 659	        } else {
 660	            if (comptime builtin.target.os.tag.isDarwin()) {
 661	                log.warn("ghostty terminfo not found, using xterm-256color", .{});
 662	                log.warn("the terminfo SHOULD exist on macos, please ensure", .{});
 663	                log.warn("you're using a valid app bundle.", .{});
 664	            }
 665	
 735	            const manpath_key = "MANPATH";
 736	            if (std.mem.print(&buf, "{s}/../man", .{resources_dir})) |man_dir| {
 737	                // Always append with colon in front, as it mean that if
 738	                // `MANPATH` is empty, then it should be treated as an extra
 739	                // path instead of overriding all paths set by OS.
 740	                try env.put(
 741	                    manpath_key,
 742	                    try appendEnvAlways(
 743	                        alloc,
 744	                        env.get(manpath_key) orelse "",
 745	                        man_dir,
 746	                    ),
 747	                );
 748	            } else |err| {
 749	                log.warn("error building {s}; man pages may not be available; err={}", .{ manpath_key, err });
 750	            }
 751	        }
 752	
 753	        // Set environment variables used by some programs (such as neovim) to detect
 754	        // which terminal emulator and version they're running under.
 755	        try env.put("TERM_PROGRAM", "ghostty");
 756	        try env.put("TERM_PROGRAM_VERSION", build_config.version_string);
 757	
 758	        // VTE_VERSION is set by gnome-terminal and other VTE-based terminals.
 759	        // We don't want our child processes to think we're running under VTE.
 760	        // This is not apprt-specific, so we do it here.
 761	        _ = env.orderedRemove("VTE_VERSION");
 762	
 763	        // Setup our shell integration, if we can.
 764	        const shell_command: configpkg.Command = shell: {
 765	            const default_shell_command: configpkg.Command =
 766	                cfg.command orelse .{ .shell = switch (builtin.target.os.tag) {
 767	                    .windows => "cmd.exe",
 768	                    else => "sh",
 769	                } };
 770	
 771	            // Always set up shell features (GHOSTTY_SHELL_FEATURES). These are
 772	            // used by both automatic and manual shell integrations.
 773	            try shell_integration.setupFeatures(
 774	                &env,
 775	                cfg.shell_integration_features,
 776	                cfg.cursor_blink orelse true,
 777	            );
 778	
 779	            const force: ?shell_integration.Shell = switch (cfg.shell_integration) {
 780	                .none => {
 781	                    // This is a source of confusion for users despite being
 782	                    // opt-in since it results in some Ghostty features not
 783	                    // working. We always want to log it.
 784	                    log.info("shell integration disabled by configuration", .{});
 785	                    break :shell default_shell_command;
 786	                },
 787	
 788	                .detect => null,
 789	                .bash => .bash,
 790	                .elvish => .elvish,
 791	                .fish => .fish,
 792	                .nushell => .nushell,
 793	                .zsh => .zsh,
 794	            };
 795	
 796	            const dir = cfg.resources_dir orelse {
 797	                log.warn("no resources dir set, shell integration disabled", .{});
 798	                break :shell default_shell_command;
 799	            };
 800	
 801	            const integration = try shell_integration.setup(
 802	                alloc,
 803	                dir,
 804	                default_shell_command,
 805	                &env,
 806	                force,
 807	            ) orelse {
 808	                log.warn("shell could not be detected, no automatic shell integration will be injected", .{});
 809	                break :shell default_shell_command;
 810	            };
 811	
 812	            log.info(
 813	                "shell integration automatically injected shell={}",
 814	                .{integration.shell},
 815	            );
 816	
 817	            break :shell integration.command;
 818	        };
 819	
 820	        // Add the environment variables that override any others.
 821	        {
 822	            var it = cfg.env_override.iterator();
 823	            while (it.next()) |entry| try env.put(
 824	                entry.key_ptr.*,
 825	                entry.value_ptr.*,
 826	            );
 827	        }
 828	
 829	        // Build our args list
 830	        const args: []const [:0]const u8 = execCommand(
 831	            alloc,
 832	            shell_command,
 833	            internal_os.passwd,
 834	        ) catch |err| switch (err) {
 835	            // If we fail to allocate space for the command we want to
 836	            // execute, we'd still like to try to run something so
 837	            // Ghostty can launch (and maybe the user can debug this further).
 838	            // Realistically, if you're getting OOM, I think other stuff is
 839	            // about to crash, but we can try.
 840	            error.OutOfMemory => oom: {
 841	                log.warn("failed to allocate space for command args, falling back to basic shell", .{});
 842	
 843	                // The comptime here is important to ensure the full slice
 844	                // is put into the binary data and not the stack.
 845	                break :oom comptime switch (builtin.target.os.tag) {
 846	                    .windows => &.{"cmd.exe"},
 847	                    else => &.{"/bin/sh"},
 848	                };
 849	            },
 850	
 851	            // This logs on its own, this is a bad error.
 852	            error.SystemError => return err,
 853	        };
 854	
 855	        // We have to copy the cwd because there is no guarantee that
 856	        // pointers in full_config remain valid.
 857	        const cwd: ?[:0]u8 = if (cfg.working_directory) |cwd|
 858	            try alloc.dupeSentinel(u8, cwd, 0)
 859	        else
 860	            null;
 861	
 862	        // Propagate the current working directory (CWD) to the shell, enabling
 863	        // the shell to display the current directory name rather than the
 864	        // resolved path for symbolic links. This is important and based
 865	        // on the same behavior in Konsole and Kitty (see the linked issues):
 866	        // https://bugs.kde.org/show_bug.cgi?id=242114
 867	        // https://github.com/kovidgoyal/kitty/issues/1595
 868	        // https://github.com/ghostty-org/ghostty/discussions/7769
 869	        if (cwd) |pwd| try env.put("PWD", pwd);
 870	
 871	        return .{
 872	            .arena = arena,
 873	            .env = env,
 874	            .cwd = cwd,
 875	            .args = args,
 876	
 877	            .rt_pre_exec_info = cfg.rt_pre_exec_info,
 878	            .rt_post_fork_info = cfg.rt_post_fork_info,
 879	
 880	            // Should be initialized with initTerminal call.
 881	            .grid_size = .{},
 882	            .screen_size = .{ .width = 1, .height = 1 },
 883	        };
 884	    }
