 933	        /// Hand the runs of printable codepoints in cps to the handler as
 934	        /// print_slice actions, so it can process them with per-run
 935	        /// rather than per-codepoint overhead, and execute the controls
 936	        /// between them. ASCII comes as bytes (u8), and then every run
 937	        /// is printable ASCII. `buf` may be overwritten unless it holds
 938	        /// cps.
 939	        inline fn printRuns(
 940	            self: *Self,
 941	            comptime Cp: type,
 942	            cps: []const Cp,
 943	            buf: []u32,
 944	        ) void {
 945	            const ascii = Cp == u8;
 946	            var i: usize = 0;
 947	            while (i < cps.len) {
 948	                const cp = cps[i];
 949	                // C0 and UTF-8-decoded C1 controls never enter
 950	                // printable runs. A codepoint is one of those
 951	                // exactly when it has no bit set outside 0x9F:
 952	                // bits 0-4 and bit 7 cover 0x00-0x1F and
 953	                // 0x80-0x9F and nothing else, so a single
 954	                // AND-test classifies both ranges. ASCII has no C1.
 955	                const control = if (ascii) cp < 0x20 else (cp & ~@as(u32, 0x9F)) == 0;
