 957	                    @branchHint(.unlikely);
 958	                    if (ascii or cp <= 0x1F) {
 959	                        // C0 controls execute rather than print.
 960	                        self.execute(@intCast(cp));
 961	                    } else {
 962	                        // C1 controls decoded from UTF-8 are ignored.
