    17	    /// drops and ignores unknown APC values.
    18	    unknown_max_bytes: usize = 0,
    19	
    20	    /// Maximum bytes each APC protocol can buffer. This is to prevent
    21	    /// malicious input from causing us to allocate too much memory.
    22	    /// If you want to be lazy and set a single value for all protocols,
    23	    /// use `.initFull`.
    24	    max_bytes: std.EnumMap(Protocol, usize) = .initFullWith(.{
    25	        .kitty = Protocol.defaultMaxBytes(.kitty),
    26	        .glyph = Protocol.defaultMaxBytes(.glyph),
    27	    }),
    28	
    29	    /// Protocols recognized by this APC handler. When a protocol is absent,
    30	    /// matching APC sequences are ignored and are not reported as unknown.
    31	    enabled: std.EnumSet(Protocol) = .full,
    32	
    33	    pub fn deinit(self: *Handler) void {
    34	        self.state.deinit();
    35	    }
    36	
    37	    pub fn start(self: *Handler) void {
    38	        self.state.deinit();
    39	        self.state = .{ .identify = .{} };
    40	    }
    41	
    42	    /// Enable or disable APC protocol recognition for future APC sequences.
    43	    /// This does not affect any APC command already being parsed.
    44	    pub fn enable(self: *Handler, protocol: Protocol, enabled: bool) void {
    45	        self.enabled.setPresent(protocol, enabled);
    46	    }
    47	
    48	    pub fn feed(self: *Handler, alloc: Allocator, byte: u8) void {
    49	        switch (self.state) {
    50	            .inactive => unreachable,
    51	
    52	            // We're ignoring this APC command, likely because we don't
    53	            // recognize it so there is no need to store the data in memory.
    54	            .ignore => return,
    55	
    56	            // Unsupported APC content is retained only when enabled.
    57	            .unknown => |*unknown| unknown.append(&.{byte}),
    58	
    59	            // We identify the APC command by the first byte.
    60	            .identify => |*id| id: {
    61	                // Kitty graphics is detected immediately on the `G` byte,
    62	                // since commands begin immediately after with no termination
    63	                // character after the 'G'.
    64	                if (id.len == 0 and byte == 'G') {
    65	                    if (comptime build_options.kitty_graphics) {
    66	                        if (self.enabled.contains(.kitty)) {
    67	                            self.state = .{ .kitty = .init(
    68	                                alloc,
    69	                                self.max_bytes.get(.kitty) orelse
    70	                                    Protocol.defaultMaxBytes(.kitty),
    71	                            ) };
    72	                        } else {
    73	                            self.state = .ignore;
    74	                        }
    75	                    } else {
    76	                        self.state = .ignore;
    77	                    }
    78	                    break :id;
    79	                }
    80	
    81	                // If we hit `;` then identify...
    82	                if (byte == ';') {
    83	                    const str = id.buf[0..id.len];
    84	                    if (std.mem.eql(u8, str, glyph.identifier)) {
    85	                        if (comptime build_options.glyph_protocol) {
    86	                            if (self.enabled.contains(.glyph)) {
    87	                                self.state = .{ .glyph = .init(
    88	                                    alloc,
    89	                                    self.max_bytes.get(.glyph) orelse
    90	                                        Protocol.defaultMaxBytes(.glyph),
    91	                                ) };
    92	                            } else {
    93	                                self.state = .ignore;
    94	                            }
    95	                        } else {
    96	                            self.state = .ignore;
    97	                        }
    98	                    } else {
    99	                        self.beginUnknown(alloc, str, &.{byte});
   100	                    }
   101	
   102	                    break :id;
   103	                }
   104	
   105	                // If we're out of identification space, the identifier is
   106	                // unsupported. Preserve the buffered prefix before replacing
   107	                // the identify union state.
   108	                if (id.len >= id.buf.len) {
   109	                    self.beginUnknown(alloc, id.buf[0..id.len], &.{byte});
   110	                    break :id;
   111	                }
   112	
   113	                const expected_idx: usize = id.len;
   114	                id.buf[id.len] = byte;
   115	                id.len += 1;
   116	
   117	                // Once the buffered input is no longer a prefix of a known
   118	                // protocol, it is an unsupported identifier.
   119	                if (self.unknown_max_bytes > 0 and
   120	                    byte != glyph.identifier[expected_idx])
   121	                {
   122	                    self.beginUnknown(alloc, id.buf[0..id.len], &.{});
   123	                }
   124	            },
   125	
   126	            .kitty => |*p| if (comptime build_options.kitty_graphics) {
   127	                p.feed(byte) catch |err| {
   128	                    log.warn("kitty graphics protocol error: {}", .{err});
   129	                    p.deinit();
   130	                    self.state = .ignore;
   131	                };
   132	            } else unreachable,
   133	
   134	            .glyph => |*p| if (comptime build_options.glyph_protocol) {
   135	                p.feed(byte) catch |err| {
   136	                    log.warn("glyph protocol error: {}", .{err});
   137	                    p.deinit();
   138	                    self.state = .ignore;
   139	                };
   140	            } else unreachable,
   141	        }
   142	    }
