1223	        /// Bulk-consume CSI parameter bytes (digits and separators)
1224	        /// and, if reached, the final byte (dispatching the CSI).
1225	        /// Returns the number of bytes consumed. Stops at the first
1226	        /// byte that isn't handled here, leaving the parser in the
1227	        /// csi_param state so the caller can process that byte.
1228	        fn consumeCsiParams(self: *Self, input: []const u8) usize {
1229	            const p = &self.parser;
1230	            assert(p.state == .csi_param);
1231	
1232	            // Accumulate parser state in locals for the hot loop. We
1233	            // use a wider accumulator so we can clamp once per digit
1234	            // while preserving the parser's saturating u16 behavior.
1235	            var acc: u32 = p.param_acc;
1236	            var acc_idx = p.param_acc_idx;
1237	            var idx = p.params_idx;
1238	
1239	            var offset: usize = 0;
1240	            while (offset < input.len) {
1241	                const c = input[offset];
1242	
1243	                // A parameter digit. Sequences with too many
1244	                // parameters are dropped at dispatch.
1245	                const digit = c -% '0';
1246	                if (digit < 10) {
1247	                    acc = @min(acc * 10 + digit, std.math.maxInt(u16));
1248	                    acc_idx |= 1;
1249	                    offset += 1;
1250	                    continue;
1251	                }
1252	
1253	                switch (c) {
1254	                    // A parameter separator.
1255	                    ':', ';' => {
1256	                        if (idx < Parser.MAX_PARAMS) {
1257	                            p.params[idx] = @intCast(acc);
1258	                            if (c == ':') p.params_sep.set(idx);
1259	                            idx += 1;
1260	                            acc = 0;
1261	                            acc_idx = 0;
1262	                        }
1263	                        offset += 1;
1264	                    },
1265	
1266	                    // A final byte: dispatch the CSI.
1267	                    0x40...0x7E => {
1268	                        p.param_acc = @intCast(acc);
1269	                        p.param_acc_idx = acc_idx;
1270	                        p.params_idx = idx;
1271	                        self.csiDispatchFinal(c);
1272	                        return offset + 1;
1273	                    },
1274	
1275	                    // Anything else (C0 controls, intermediates, etc.)
1276	                    // is handled by the caller.
1277	                    else => break,
1278	                }
1279	            }
1280	
1281	            p.param_acc = @intCast(acc);
1282	            p.param_acc_idx = acc_idx;
1283	            p.params_idx = idx;
1284	            return offset;
1285	        }
