1300	
1301	            var end: usize = 0;
1302	            if (comptime std.simd.suggestVectorLength(u8)) |vector_len| {
1303	                const ByteVector = @Vector(vector_len, u8);
1304	                while (end + vector_len <= input.len) {
1305	                    const bytes: ByteVector = input[end..][0..vector_len].*;
1306	                    const invalid = (bytes == @as(ByteVector, @splat(0x18))) |
1307	                        (bytes == @as(ByteVector, @splat(0x1A))) |
1308	                        (bytes == @as(ByteVector, @splat(0x1B))) |
1309	                        (bytes >= @as(ByteVector, @splat(0x80)));
1310	                    if (@reduce(.Or, invalid)) break;
1311	                    end += vector_len;
1312	                }
1313	            }
